{
 "quarter": "Q1 FY27",
 "callDate": "2026-07-18",
 "guidance": [
  {
   "metric": "margin",
   "statement": "Cost of funds can see a 40 to 50 basis points change, but not in a hurry.",
   "quote": "compared to our historical norms as well as compared to what we have seen in the industry as such, there can be 40, 50 basis points change, but it is not going to change in a hurry.",
   "page": 5,
   "horizon": "medium term",
   "quantitative": true
  },
  {
   "metric": "margin",
   "statement": "Management targets a retail asset mix of around 60% in the long term.",
   "quote": "we were at about 60% or so and we always have thought that India's consumption component of the GDP is at about 60% and that's where we want to be as far as the retail mix is concerned",
   "page": 8,
   "horizon": "long term",
   "quantitative": true
  },
  {
   "metric": "other",
   "statement": "Endeavor is to reach a CASA ratio near pre-merger levels of around 38% to 40%.",
   "quote": "the endeavor and our vision is to reach to somewhere near the pre-merger levels or just around the time of the merger, which was around 38.",
   "page": 9,
   "quantitative": true,
   "horizon": "medium to long term"
  },
  {
   "metric": "profit",
   "statement": "Long-term profit growth should be at or above balance sheet growth.",
   "quote": "We do think that in the longer term that the profit growth should be at or above the balance sheet growth.",
   "page": 11,
   "quantitative": false,
   "horizon": "longer term"
  }
 ],
 "delivered": [
  {
   "metric": "deposits",
   "statement": "Deposit growth continues to be relatively better than historical Q1 trends with market share gains.",
   "page": 3
  },
  {
   "metric": "branch productivity",
   "statement": "Per branch metrics stand at approximately INR 330 crores per branch.",
   "page": 6
  },
  {
   "metric": "advances",
   "statement": "Corporate and wholesale segment advances grew at approximately 18% year-on-year.",
   "page": 12
  },
  {
   "metric": "loans",
   "statement": "MSME business banking segment grew at 22.3% year-on-year.",
   "page": 13
  },
  {
   "metric": "loans",
   "statement": "Disbursements under ECLGS scheme 5.0 reached close to INR 14,000 crores by June 30.",
   "page": 13
  },
  {
   "metric": "margin",
   "statement": "Cost of funds moderated by about 40 basis points year-on-year.",
   "page": 15
  }
 ],
 "tone": "Confident in core franchise resilience and demand, while managing tactical margin and CASA pressures.",
 "pushback": [
  {
   "topic": "Margin Bottoming and Levers",
   "gist": "Analysts questioned whether margins have bottomed out and what specific levers remain to recover them.",
   "page": 5
  },
  {
   "topic": "CASA Market Share Decline",
   "gist": "Repeated concern over the drop in CASA ratio post-merger and whether historical ratios can be restored.",
   "page": 6
  },
  {
   "topic": "Earnings vs Balance Growth",
   "gist": "Scepticism on profit growth lagging balance sheet growth significantly over recent periods.",
   "page": 11
  },
  {
   "topic": "Saturday Earnings Calls",
   "gist": "An analyst strongly urged management to move away from Saturday earnings calls to weekday reporting for better global participation.",
   "page": 16
  }
 ]
}
